import assert from "node:assert/strict";

export function retryPlan({ attempt, transient, idempotent }) {
  if (!Number.isInteger(attempt) || attempt < 1) throw new TypeError("Invalid attempt");
  if (transient !== true || idempotent !== true || attempt >= 3) return { retry: false, delayMs: 0 };
  return { retry: true, delayMs: Math.min(100 * (2 ** (attempt - 1)), 1000) };
}
console.log(JSON.stringify([
  retryPlan({ attempt: 1, transient: true, idempotent: true }),
  retryPlan({ attempt: 1, transient: true, idempotent: false }),
  retryPlan({ attempt: 3, transient: true, idempotent: true }),
]));
assert.deepEqual(retryPlan({ attempt: 2, transient: true, idempotent: true }), { retry: true, delayMs: 200 });
assert.equal(retryPlan({ attempt: 1, transient: false, idempotent: true }).retry, false);
assert.throws(() => retryPlan({ attempt: 0, transient: true, idempotent: true }), TypeError);
assert.equal(retryPlan({ attempt: 1, transient: true, idempotent: false }).retry, false);

import assert from "node:assert/strict";

export function decidePaidAccess({ principal, entitlement, requiredTier, now }) {
  if (!principal || typeof principal.userId !== "string" || !principal.userId) return 401;
  const ranks = { pro: 1, expert: 2 };
  if (!Object.hasOwn(ranks, requiredTier) || !Number.isFinite(now)) return 403;
  if (!entitlement || entitlement.userId !== principal.userId || !Object.hasOwn(ranks, entitlement.tier)) return 403;
  const expiry = Date.parse(entitlement.expiresAt);
  if (!Number.isFinite(expiry) || expiry <= now) return 403;
  return ranks[entitlement.tier] >= ranks[requiredTier] ? 200 : 403;
}
const now = Date.parse("2030-01-01T00:00:00Z");
const principal = { userId: "user-a" };
const entitlement = { userId: "user-a", tier: "pro", expiresAt: "2030-02-01T00:00:00Z" };
console.log(decidePaidAccess({ principal, entitlement, requiredTier: "pro", now }));
console.log(decidePaidAccess({ principal, entitlement, requiredTier: "expert", now }));
console.log(decidePaidAccess({ principal: null, entitlement, requiredTier: "pro", now }));
assert.equal(decidePaidAccess({ principal, entitlement: { ...entitlement, userId: "user-b" }, requiredTier: "pro", now }), 403);
assert.equal(decidePaidAccess({ principal, entitlement: { ...entitlement, expiresAt: "2029-01-01T00:00:00Z" }, requiredTier: "pro", now }), 403);
assert.equal(decidePaidAccess({ principal, entitlement, requiredTier: "__proto__", now }), 403);
assert.equal(decidePaidAccess({ principal, entitlement, requiredTier: "expert", now }), 403);
assert.equal(decidePaidAccess({ principal: null, entitlement, requiredTier: "pro", now }), 401);

import assert from "node:assert/strict";

export function releaseDecision(evidence) {
  if (!evidence || !Number.isFinite(evidence.errorRate) || evidence.errorRate < 0 || evidence.errorRate > 1) return "hold";
  if (!Number.isFinite(evidence.p95Ms) || evidence.p95Ms < 0) return "hold";
  if (!Number.isInteger(evidence.sampleSize) || evidence.sampleSize < 100) return "hold";
  if (evidence.restoreTested !== true || evidence.rollbackTested !== true) return "hold";
  return evidence.errorRate <= 0.01 && evidence.p95Ms <= 500 ? "release" : "hold";
}
const baseline = { errorRate: 0.005, p95Ms: 250, sampleSize: 200, restoreTested: true, rollbackTested: true };
console.log(releaseDecision({ ...baseline, restoreTested: false }));
console.log(releaseDecision(baseline));
console.log(releaseDecision({ ...baseline, errorRate: NaN }));
assert.equal(releaseDecision({ ...baseline, p95Ms: 501 }), "hold");
assert.equal(releaseDecision({ ...baseline, sampleSize: 99 }), "hold");
assert.equal(releaseDecision({ ...baseline, rollbackTested: false }), "hold");
assert.equal(releaseDecision({ ...baseline, restoreTested: false }), "hold");
